"""to_dense_backward (Gems / FlagGems) — baseline.

Semantics established experimentally against the native aten reference on the
target backend (H20-3e, torch 2.10):

* strided input -> grad converted to the scalar type of input, keeping grad's
  stored values and shape; input shape/stride/contiguity is irrelevant and the
  native operator returns `grad` itself when the scalar types already agree.
* COO + masked branch (omitted / None / True / any nonzero int)
  -> grad.sparse_mask(input.coalesce()).
* COO + unmasked branch (False / int 0) -> grad.to_sparse(input.sparse_dim()).
* CSR/CSC/BSR/BSC: the same values/indices re-wrapped in input.layout(); a
  non-hybrid compressed operand converts its sparse dimensions through the
  matching compressed converter, a hybrid operand keeps grad.to_sparse(k).

Numerics: the strided conversion is carried out by the @triton.jit cast kernel.
Torch's float->unsigned conversion truncates toward zero and then wraps
(`(uint8)(int32)(-1.75) == 255`), while a direct float->uint8 store saturates,
so the unsigned case converts through int32 inside the kernel.  The cast is
wrapped in an autograd.Function whose backward is the same device kernel cast
back to grad's dtype, which is what the native `grad.to(dtype)` graph provides.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_CBLOCK = 4096


@triton.jit
def _cast_kernel(
    g_ptr, o_ptr, n,
    MODE: tl.constexpr,  # 0 = plain cast, 1 = bool, 2 = unsigned wrap via int32
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    off = pid * BLOCK + tl.arange(0, BLOCK)
    m = off < n
    x = tl.load(g_ptr + off, mask=m)
    if MODE == 1:
        tl.store(o_ptr + off, x != 0, mask=m)
    elif MODE == 2:
        tl.store(o_ptr + off, x.to(tl.int32), mask=m)
    else:
        tl.store(o_ptr + off, x, mask=m)


def _mode_of(dtype):
    if dtype == torch.bool:
        return 1
    if dtype.is_floating_point or dtype.is_complex:
        return 0
    if dtype.is_signed:
        return 0
    return 2


def _cast_copy(grad, dtype):
    """Device-kernel conversion of grad to `dtype`, preserving shape."""
    src = grad if grad.is_contiguous() else grad.contiguous()
    out = torch.empty(grad.shape, dtype=dtype, device=grad.device)
    n = out.numel()
    if n:
        _cast_kernel[(triton.cdiv(n, _CBLOCK),)](src, out, n, _mode_of(dtype), _CBLOCK)
    return out


class _Cast(torch.autograd.Function):
    """Autograd wrapper: both directions are the same device cast kernel."""

    @staticmethod
    def forward(ctx, x, dtype):
        ctx.src_dtype = x.dtype
        return _cast_copy(x, dtype)

    @staticmethod
    def backward(ctx, g):
        return _cast_copy(g, ctx.src_dtype), None


def _norm_masked(masked_grad):
    if masked_grad is None:
        return True
    if isinstance(masked_grad, bool):
        return masked_grad
    if isinstance(masked_grad, int):
        return masked_grad != 0
    raise TypeError("to_dense_backward: masked_grad must be an Optional[bool]")


def _block(input):
    return tuple(int(v) for v in input.values().shape[1:3])


def to_dense_backward(grad, input, masked_grad=None):
    logger.debug('GEMS TO_DENSE_BACKWARD')
    if not torch.is_tensor(grad):
        raise TypeError("to_dense_backward: grad must be a Tensor")
    masked = _norm_masked(masked_grad)
    layout = input.layout

    if layout == torch.strided:
        if grad.dtype == input.dtype:
            return grad
        return _Cast.apply(grad, input.dtype)

    if layout == torch.sparse_coo:
        if masked:
            return grad.sparse_mask(input.coalesce())
        return grad.to_sparse(input.sparse_dim())

    k = input.sparse_dim()
    if masked:
        base = grad.sparse_mask(input)
    elif input.dense_dim() == 0 and grad.dim() > k:
        base = grad.to_sparse_csr() if layout == torch.sparse_csr else grad.to_sparse_csc()
    else:
        base = grad.to_sparse(k)

    if layout == torch.sparse_csr:
        return base.to_sparse_csr()
    if layout == torch.sparse_csc:
        return base.to_sparse_csc()
    blk = _block(input)
    if layout == torch.sparse_bsr:
        return base.to_sparse_bsr(blk)
    return base.to_sparse_bsc(blk)
